INSERT INTO `partners` (`id`, `title`, `image`, `description`, `status`, `order`, `created_at`, `updated_at`) VALUES
(1, 'Maharashtra Forest Department', 'http://localhost:8000/file-manager/Partners/6a731866c9aa9.jpg', 'Working closely with the state\'s primary environmental guardians to protect biodiversity, restore degraded lands, and implement impactful conservation strategies across protected zones and reserves.', 1, 1, '2026-08-05 05:33:26', '2026-08-05 05:33:26'),
(2, 'Flipkart', 'http://localhost:8000/file-manager/Partners/6a731cfb4093d.webp', 'Partnering to drive sustainable e-commerce initiatives and large-scale afforestation drives across India. Together, we are building a greener supply chain and offsetting carbon footprints through direct community action.', 1, 2, '2026-08-05 05:52:58', '2026-08-05 05:52:58'),
(3, 'Maharashtra State Board of Secondary & Higher Secondary Education Pune Division', 'http://localhost:8000/file-manager/Partners/6a731cfd4f6ba.png', 'Integrating environmental education into the core curriculum, empowering the next generation of students with the knowledge and tools to protect our planet through school-level eco-clubs and practical learning.', 1, 3, '2026-08-05 05:53:41', '2026-08-05 05:53:41'),
(4, 'Social Forestry Department Maharashtra', 'http://localhost:8000/file-manager/Partners/6a731cfc054f4.webp', 'Collaborating on community-led tree plantation campaigns, transforming barren landscapes into thriving social forests that benefit local communities, provide sustainable livelihoods, and enrich the ecosystem.', 1, 4, '2026-08-05 05:54:07', '2026-08-05 05:54:07');
