INSERT INTO `testimonials` (`id`, `name`, `designation`, `testimonial`, `is_show_on_home`, `date`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Priya Sharma', NULL, 'The program introduced our students to environmental conservation in an engaging and practical way. Through plantation drives, waste segregation workshops, nature walks, and classroom discussions, children developed a deeper appreciation for the environment. The curriculum was thoughtfully designed to combine theory with action, encouraging students to become responsible citizens and active contributors to a greener future.', 0, '2026-03-15', 1, '2026-08-05 07:30:38', '2026-08-05 07:30:38');
